import{_ as e,o as s,c as a,ae as n,j as i,t as l,a as d}from"./chunks/framework.DFTT1zkb.js";const o="/docs/hgu.png",p="/docs/motto.png",x=JSON.parse('{"title":"学校概况","description":"","frontmatter":{},"headers":[],"relativePath":"begin/intro.md","filePath":"begin/intro.md"}'),r={name:"begin/intro.md"},c={class:"timeline-dot"},m={class:"timeline-dot-title"};function v(_,t,h,g,u,f){return s(),a("div",null,[t[1]||(t[1]=n('<h1 id="学校概况" tabindex="-1">学校概况 <a class="header-anchor" href="#学校概况" aria-label="Permalink to &quot;学校概况&quot;">​</a></h1><p align="center"><img src="'+o+'" width="200" alt="logo"></p><p>河北地质大学是自然资源部、河北省人民政府共建大学，省属重点骨干大学。河北省重点支持的国内一流大学建设高校。</p><p>学校始建于1953年，由著名地质学家李四光、老一辈革命家何长工选址塞外古城宣化成立中央人民政府地质部宣化地质学校，是新中国最早设置经济管理类专业的原地质部直属五大院校之一；1971年改办河北地质学院；1985年，从宣化迁至省会石家庄办学；1996年，更名为石家庄经济学院；2016年，定名为河北地质大学。</p><p>截至2025年5月，学校主校区占地1775亩，建筑面积65万平方米。学校设有8个学科门类，16个二级学院（部），涵盖70个本科专业，并拥有地质学等12个一级学科硕士学位授权和13个专业硕士学位授权；拥有同等学力硕士学位授予权。地球科学进入ESI全球排名前1%。全校在校生约18000人，教职员工1700余人。</p><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><div class="timeline-dot"><span class="timeline-dot-title">1953</span><p>由李四光、何长工选址塞外古城宣化市（现为张家口市宣化区）成立了新中国最早的唯一的设置有经济类专业的地质院校——中央人民政府地质部宣化地质学校，是直属于地质部领导的5所院校之一</p></div><div class="timeline-dot"><span class="timeline-dot-title">1955</span><p>学校法定名称由“中央人民政府地质部宣化地质学校”，改为“地质部宣化地质学校”</p></div><div class="timeline-dot"><span class="timeline-dot-title">1965</span><p>归属河北省地质局领导</p></div><div class="timeline-dot"><span class="timeline-dot-title">1970</span><p>学校校名改为“河北省宣化地质学校”</p></div><div class="timeline-dot"><span class="timeline-dot-title">1971</span><p>改办河北地质学院，学院以省管为主，党的关系隶属院所在地市党委</p></div><div class="timeline-dot"><span class="timeline-dot-title">1996</span><p>河北地质学院更名为石家庄经济学院</p></div><div class="timeline-dot"><span class="timeline-dot-title">2016.03</span><p>经中华人民共和国教育部批准，石家庄经济学院更名为河北地质大学</p></div><div class="timeline-dot"><span class="timeline-dot-title">2021</span><p>在省委、省政府的领导和石家庄市委、市政府的支持下，12月27日，河北地质大学与石家庄市国控城发投集团签署新校区工程代建协议；12月28日，河北地质大学新校区建设开工</p></div><div class="timeline-dot"><span class="timeline-dot-title">2024.09</span><p>新校区启用，6300余名学生首批入驻新校区</p></div><div class="timeline-dot"><span class="timeline-dot-title">2025</span><p>秋季开学前，学校将整体搬迁至新校区</p></div><div class="timeline-dot"><span class="timeline-dot-title">2026.01</span><p>河北地质大学博物馆新馆正式落成，位于石家庄滹沱河畔的河北地质大学新校区</p></div>',17)),i("div",c,[i("span",m,l(new Date().getFullYear()),1),t[0]||(t[0]=i("p",null,"正在谱写新的未来...",-1))]),t[2]||(t[2]=i("h2",{id:"校训",tabindex:"-1"},[d("校训 "),i("a",{class:"header-anchor",href:"#校训","aria-label":'Permalink to "校训"'},"​")],-1)),t[3]||(t[3]=i("p",{align:"center"},[i("img",{src:p,width:"400",alt:"motto"})],-1))])}const P=e(r,[["render",v]]);export{x as __pageData,P as default};
